import {shouldContinueToolLoop, aggregateUsage} from './orchestratorHelpers.js';
import type {ToolRegistry} from './tools/registry.js';
import type {ToolCall} from '../types/ai.js';

// All three conditions matter; dropping the registry check spins the tool loop.

const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
const REGISTRY = {} as ToolRegistry;

describe('shouldContinueToolLoop', () => {
  it('continues when the model requested a tool and a registry can run it', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
  });

  it('stops when no registry is configured, whatever the model asked for', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
  });

  it('stops when the model named no tool', () => {
    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
  });

  it('stops when the model finished for a reason other than tool use', () => {
    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
  });
});

describe('aggregateUsage', () => {
  it('sums each token field when both sides report usage', () => {
    expect(aggregateUsage({inputTokens: 10, outputTokens: 5, totalTokens: 15}, {inputTokens: 2, outputTokens: 3, totalTokens: 5})).toEqual({inputTokens: 12, outputTokens: 8, totalTokens: 20});
  });

  it('preserves undefined when neither side reports usage', () => {
    expect(aggregateUsage(undefined, undefined)).toBeUndefined();
  });

  it('adopts the new round usage when the total is undefined', () => {
    expect(aggregateUsage(undefined, {inputTokens: 2, outputTokens: 3, totalTokens: 5})).toEqual({inputTokens: 2, outputTokens: 3, totalTokens: 5});
  });

  it('preserves the existing total when the new round reports no usage', () => {
    expect(aggregateUsage({inputTokens: 10, outputTokens: 5, totalTokens: 15}, undefined)).toEqual({inputTokens: 10, outputTokens: 5, totalTokens: 15});
  });
});
